def smallest_change(arr: list[int]) -> int:
    if len(arr) == 0:
        return 0

    n = len(arr)

    # Create a dictionary to store the frequency of each element
    freq: dict[int, int] = {}

    # Create a list to store the reversed array
    rev_arr = arr[::-1]

    # Calculate the frequency of each element in the original array
    for num in arr:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Calculate the frequency of each element in the reversed array
    for num in rev_arr:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Initialize the count of changes needed
    count = 0

    # Iterate over the unique elements in the frequency dictionary
    for key in freq:
        # If the frequency of the element in the original array is different from the frequency in the reversed array
        if freq[key] != freq[key] * 2:
            # Calculate the number of changes needed for this element
            count += abs(freq[key] - (freq[key] // 2) * 2)

    return count
