def encode(message):
    """
    Encodes a message by swapping case and replacing vowels.

    Parameters:
    message (str): The input message to be encoded.

    Returns:
    str: The encoded message.
    """
    vowels = "aeiouAEIOU"
    encoded_message = ""

    for char in message:
        if char in vowels:
            # Replace vowels with the letter 2 places ahead
            if char.lower() in "aeiou":
                encoded_message += chr((ord(char) - ord("a") + 2) % 26 + ord("a"))
            else:
                encoded_message += chr((ord(char) - ord("A") + 2) % 26 + ord("A"))
        else:
            # Swap case for non-vowels
            if char.isupper():
                encoded_message += char.lower()
            else:
                encoded_message += char.upper()

    return encoded_message
