def skjkasdkd(lst: list[int]) -> int:
    from itertools import count

    def is_prime(num: int) -> bool:
        if num <= 1:
            return False
        for i in count(2):
            if num % i == 0:
                return False
            if i * i > num:
                break
        return True

    if not lst:
        return 0

    largest_prime = max(lst, key=lambda x: x if is_prime(x) else 0)
    return sum(int(digit) for digit in str(largest_prime))
