    # Check if the array can be sorted by shifting
    sorted_arr = sorted(arr)
    for i in range(len(arr)):
        # Check if the array can be sorted by shifting the first i elements
        if arr[:i] + arr[i + 1 :] == sorted_arr[:i] + sorted_arr[i + 1 :]:
            return True

    return False
