def match_parens(lst: list[str]) -> str:
    def helper(s: str) -> bool:
        # Helper function to check if a string of parentheses is balanced
        open_count = 0
        for char in s:
            if char == "(":
                open_count += 1
            elif char == ")":
                open_count -= 1
                if open_count < 0:
                    return False
        return open_count == 0

    # Check if either string can form a balanced string on its own
    if helper(lst[0]):
        return "Yes"
    if helper(lst[1]):
        return "Yes"

    # Check if they can form a balanced string when concatenated in some order
    s1 = lst[0]
    s2 = lst[1]
    s1_reversed = s1[::-1]

    # Check all possible concatenations
    if helper(s1 + s2) or helper(s2 + s1) or helper(s1_reversed + s2) or helper(
        s2 + s1_reversed
    ):
        return "Yes"

    return "No"

