    if n <= 0:
        return 0
    # Calculate a[i] = i * i - i + 1 for each i in range(1, n + 1)
    a = [i * i - i + 1 for i in range(1, n + 1)]

    # Initialize a list to store the count of numbers in a that are congruent to 0, 1, and 2 modulo 3
    count_0, count_1, count_2 = 0, 0, 0

    # Count the occurrences of each residue modulo 3
    for num in a:
        if num % 3 == 0:
            count_0 += 1
        elif num % 3 == 1:
            count_1 += 1
        else:
            count_2 += 1

    # Initialize the answer with the minimum of count_0 and count_1 + count_2
    ans = min(count_0, count_1 + count_2)

    # Iterate over all possible triples (i, j, k) where i < j < k
    for i in range(1, n - 1):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                # Check if the sum a[i] + a[j] + a[k] is a multiple of 3
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    # If it is, update the answer
                    ans = max(ans, 1)

    return ans
