def eat(number: int, need: int, remaining: int) -> list[int]:
    if not (0 <= number <= 1000):
        raise ValueError("number must be between 0 and 1000")
    if not (0 <= need <= 1000):
        raise ValueError("need must be between 0 and 1000")
    if not (0 <= remaining <= 1000):
        raise ValueError("remaining must be between 0 and 1000")
    # Calculate the total number of carrots eaten
    total_eaten = number + need
    # Determine how many carrots are left after the meals
    carrots_left = max(remaining - (total_eaten - number), 0)
    return [total_eaten, carrots_left]

